// Shared helpers. build.mjs prepends this file to every Code node.

const REQUIRED_CONFIG = ['business_name', 'google_review_url', 'twilio_from_number', 'public_base_url', 'timezone'];

const CONFIG_DEFAULTS = {
  send_start_hour: '9',
  send_end_hour: '20',
  first_delay_hours: '1',
  followup1_days: '2',
  followup2_days: '6',
  stop_on_click: 'TRUE',
  ai_model: 'claude-opus-5',
  max_sends_per_run: '20',
  paused: 'FALSE',
  test_mode: 'FALSE',
  owner_phone: '',
};

const TRACKER_COLUMNS = [
  'job_id', 'created_at', 'customer_name', 'phone', 'service', 'technician', 'notes', 'consent',
  'status', 'step', 'msg1_at', 'msg2_at', 'msg3_at', 'clicked', 'clicked_at', 'reviewed',
  'opted_out', 'last_message', 'last_error',
];

function truthy(v) {
  return ['true', 'yes', 'y', '1', 'x'].includes(String(v ?? '').trim().toLowerCase());
}

function readConfig(items) {
  const cfg = { ...CONFIG_DEFAULTS };
  for (const it of items) {
    const key = String(it.json.key ?? '').trim();
    const value = String(it.json.value ?? '').trim();
    if (key && value !== '') cfg[key] = value;
  }
  const missing = REQUIRED_CONFIG.filter((k) => !cfg[k]);
  if (missing.length) {
    throw new Error('Config tab is missing: ' + missing.join(', '));
  }
  cfg.public_base_url = cfg.public_base_url.replace(/\/+$/, '');
  return cfg;
}

function normPhone(raw) {
  const d = String(raw ?? '').replace(/\D/g, '');
  if (d.length === 10) return '+1' + d;
  if (d.length === 11 && d[0] === '1') return '+' + d;
  return '';
}

// Owner phone may be outside the US (for example during testing), so any
// international number is accepted here. Customers still need a US number.
// Google Sheets drops a leading "+", so digits alone are accepted too.
function normOwnerPhone(raw) {
  const us = normPhone(raw);
  if (us) return us;
  const d = String(raw ?? '').replace(/\D/g, '');
  return d.length >= 8 && d.length <= 15 ? '+' + d : '';
}

function toTrackerRow(rec) {
  const row = {};
  for (const col of TRACKER_COLUMNS) row[col] = rec[col] ?? '';
  return row;
}

// Merges newly completed jobs into the tracker and decides, per job,
// whether to send the next message, only save a change, or do nothing.

const cfg = readConfig($('Read Config').all());
if (truthy(cfg.paused)) return [];

const now = DateTime.now().setZone(cfg.timezone);
if (!now.isValid) throw new Error('Config timezone is not valid: ' + cfg.timezone);

const startHour = Number(cfg.send_start_hour);
const endHour = Number(cfg.send_end_hour);
const inSendWindow = now.hour >= startHour && now.hour < endHour;
const firstDelayHours = Number(cfg.first_delay_hours);
const followup1Days = Number(cfg.followup1_days);
const followup2Days = Number(cfg.followup2_days);
const stopOnClick = truthy(cfg.stop_on_click);
const testMode = truthy(cfg.test_mode);
const maxSends = Number(cfg.max_sends_per_run) || 20;
const ownerPhone = normOwnerPhone(cfg.owner_phone);
if (testMode && !ownerPhone) throw new Error('test_mode is on but owner_phone is empty or not a valid number (use +country code)');

function hashId(s) {
  let h1 = 0x811c9dc5;
  let h2 = 0x9747b28c;
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    h1 = Math.imul(h1 ^ c, 16777619) >>> 0;
    h2 = Math.imul(h2 ^ c, 2246822519) >>> 0;
  }
  return h1.toString(36).padStart(7, '0') + h2.toString(36).padStart(7, '0');
}

function pick(row, test) {
  for (const [k, v] of Object.entries(row)) {
    if (test(k.toLowerCase())) return String(v ?? '').trim();
  }
  return '';
}

// Existing tracker rows, keyed by job_id.
const tracker = new Map();
for (const it of $('Read Tracker').all()) {
  const id = String(it.json.job_id ?? '').trim();
  if (id) tracker.set(id, { ...it.json });
}

const changed = new Set();

// Jobs the owner marked as completed in the Jobs tab become tracker rows.
// The Jobs tab is matched by header keywords, so column order does not matter.
function hasColumn(row, test) {
  return Object.keys(row).some((k) => test(k.toLowerCase()));
}
function yes(v) {
  const s = String(v ?? '').trim().toLowerCase();
  return s !== '' && !['false', 'no', 'n', '0'].includes(s);
}
const isCompletedCol = (k) => k.includes('complete') || k === 'status';
const isConsentCol = (k) => k.includes('agree') || k.includes('consent');

for (const it of $('Read Jobs').all()) {
  const r = it.json;
  const done = pick(r, isCompletedCol).toLowerCase();
  if (!(truthy(done) || ['complete', 'completed', 'done', 'finished'].includes(done))) continue;

  const name = pick(r, (k) => k.includes('customer') && k.includes('name'));
  const rawPhone = pick(r, (k) => k.includes('phone') || k.includes('mobile'));
  if (!name && !rawPhone) continue;
  const service = pick(r, (k) => k.includes('service'));
  const jobDate = pick(r, (k) => k.includes('date') || k === 'timestamp');
  // One review request per customer per job date (or per service if there is no date).
  const id = hashId([name, rawPhone, jobDate || service].join('|').toLowerCase());
  if (tracker.has(id)) continue;

  const phone = normPhone(rawPhone);
  // No consent column means the owner collects consent elsewhere (invoice or booking form).
  const consent = hasColumn(r, isConsentCol) ? yes(pick(r, isConsentCol)) : true;
  let status = 'pending';
  if (!phone) status = 'invalid_phone';
  else if (!consent) status = 'no_consent';

  tracker.set(id, {
    job_id: id,
    created_at: now.toUTC().toISO(),
    customer_name: name,
    phone: phone || rawPhone,
    service,
    technician: pick(r, (k) => k.includes('technician')),
    notes: pick(r, (k) => k.includes('note')),
    consent: consent ? 'TRUE' : 'FALSE',
    status,
    step: 0,
    msg1_at: '', msg2_at: '', msg3_at: '',
    clicked: 'FALSE', clicked_at: '',
    reviewed: 'FALSE', opted_out: 'FALSE',
    last_message: '', last_error: '',
  });
  changed.add(id);
}

const FINAL = ['done', 'reviewed', 'opted_out', 'clicked', 'invalid_phone', 'no_consent', 'error'];

const MESSAGE_GOALS = {
  1: 'This is the first message, sent a few hours after the job was finished. Thank them for choosing the business and ask if they would share a quick Google review.',
  2: 'This is a friendly reminder sent 2 to 3 days after the first message. They have not left a review yet. Keep it shorter and lighter than a first message. Do not guilt them.',
  3: 'This is the last reminder, about a week after the job. Say this is the last note about it and thank them either way.',
};

function claudeBody(rec, step) {
  const firstName = String(rec.customer_name || '').split(/\s+/)[0] || 'there';
  const techFirst = String(rec.technician || '').split(/\s+/)[0];
  const system = [
    `You write short SMS messages for ${cfg.business_name}, a local service business in the United States.`,
    'Each message asks a customer who recently had work done to leave a Google review.',
    'Rules:',
    '- 1 or 2 sentences, under 220 characters in total.',
    '- Warm, plain, and professional. Sound like a real person at a small local business.',
    '- Use the customer first name and mention the service. Mention the technician by first name if one is given.',
    '- Include the business name.',
    '- No links, URLs, or phone numbers. A link is added after your text.',
    '- No emojis, no hashtags, no em dashes, at most one exclamation mark.',
    '- Never offer a discount, gift, or anything in exchange for a review.',
    '- Never ask for 5 stars or a positive review. Ask for honest feedback.',
    '- Output only the message text.',
  ].join('\n');
  const details = [
    `Customer first name: ${firstName}`,
    `Service: ${rec.service || 'recent service'}`,
    techFirst ? `Technician: ${techFirst}` : 'Technician: not given',
    rec.notes ? `Job notes (use at most one small detail, only if it fits naturally): ${rec.notes}` : '',
  ].filter(Boolean).join('\n');
  return {
    model: cfg.ai_model,
    max_tokens: 1500,
    output_config: { effort: 'low' },
    fallbacks: 'default',
    system,
    messages: [{ role: 'user', content: `${MESSAGE_GOALS[step]}\n\n${details}` }],
  };
}

const out = [];
let sends = 0;

for (const [id, rec] of tracker) {
  const before = JSON.stringify(rec);

  // Manual overrides typed into the sheet by the owner.
  if (truthy(rec.opted_out) && rec.status !== 'opted_out') rec.status = 'opted_out';
  else if (truthy(rec.reviewed) && !['reviewed', 'opted_out'].includes(rec.status)) rec.status = 'reviewed';
  else if (stopOnClick && truthy(rec.clicked) && !FINAL.includes(rec.status)) rec.status = 'clicked';

  const step = Number(rec.step) || 0;
  if (step >= 3 && !FINAL.includes(rec.status)) rec.status = 'done';

  let nextStep = 0;
  if (!FINAL.includes(rec.status)) {
    const created = DateTime.fromISO(String(rec.created_at));
    const msg1 = DateTime.fromISO(String(rec.msg1_at));
    if (step === 0 && created.isValid && now.diff(created, 'hours').hours >= firstDelayHours) nextStep = 1;
    else if (step === 1 && msg1.isValid && now.diff(msg1, 'days').days >= followup1Days) nextStep = 2;
    else if (step === 2 && msg1.isValid && now.diff(msg1, 'days').days >= followup2Days) nextStep = 3;
  }

  if (nextStep && inSendWindow && sends < maxSends) {
    sends++;
    out.push({
      json: {
        ...toTrackerRow(rec),
        _action: 'send',
        _step: nextStep,
        _to: testMode ? ownerPhone : rec.phone,
        _from: normPhone(cfg.twilio_from_number) || cfg.twilio_from_number,
        _link: `${cfg.public_base_url}/webhook/review?id=${id}`,
        _business: cfg.business_name,
        _claude_body: claudeBody(rec, nextStep),
      },
    });
  } else if (changed.has(id) || JSON.stringify(rec) !== before) {
    out.push({ json: { ...toTrackerRow(rec), _action: 'save' } });
  }
}

return out;

// Turns Claude's reply into the final SMS. Falls back to a fixed template
// when the AI call failed, was declined, or returned something unusable.

const rec = $('Plan Actions').item.json;
const res = $json;
const step = rec._step;
const biz = rec._business;
const firstName = String(rec.customer_name || '').split(/\s+/)[0] || 'there';
const service = rec.service || 'recent service';

const TEMPLATES = {
  1: `Hi ${firstName}, thanks for choosing ${biz} for your ${service}. If you have a minute, would you share how it went in a quick Google review?`,
  2: `Hi ${firstName}, a quick reminder from ${biz}. Your honest feedback on your ${service} would really help others in the area.`,
  3: `Hi ${firstName}, last note from ${biz}. If you have 30 seconds, a short review of your ${service} would mean a lot. Thank you either way.`,
};

let text = '';
let note = '';
if (res && Array.isArray(res.content) && res.stop_reason !== 'refusal') {
  const block = res.content.find((b) => b.type === 'text');
  text = block ? String(block.text) : '';
} else {
  const err = res && res.error;
  note = 'AI unavailable: ' + String((err && (err.message || err)) || (res && res.stop_reason) || 'unknown').slice(0, 200);
}

text = text
  .replace(/https?:\/\/\S+|www\.\S+/gi, '')
  .replace(/\p{Extended_Pictographic}/gu, '')
  .replace(/\s*[\u2014\u2013]\s*/g, ', ')
  .replace(/\s+/g, ' ')
  .trim()
  .replace(/^["']+|["']+$/g, '')
  .trim();

if (!text || text.length > 260) {
  if (!note) note = text ? 'AI text too long, template used' : 'AI text empty, template used';
  text = TEMPLATES[step];
}

// Carriers require the sender to be identified.
if (!text.toLowerCase().includes(String(biz).toLowerCase())) text = `${biz}: ${text}`;

const body = step === 1
  ? `${text}\n\n${rec._link}\n\nReply STOP to opt out.`
  : `${text}\n\n${rec._link}`;

return { json: { ...rec, _body: body, _note: note } };

